const TEST=false;
const MONTHS=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const arr=v=>{ if(typeof v==='string'){ try{return JSON.parse(v);}catch(e){return [];} } return Array.isArray(v)?v:[]; };
const titles=arr(input.sheets).map(s=>String(((s||{}).properties||{}).title||'').trim());
let base=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
if(TEST) base=new Date(2026,10,7);
const dow=base.getDay();
const offs=(dow===4)?[1,3]:[1];
const targets=offs.map(o=>{const d=new Date(base.getFullYear(),base.getMonth(),base.getDate()+o);return {y:d.getFullYear(),m:d.getMonth()+1,d:d.getDate(),w:d.getDay()};});
const tabs=[];
for(const t of targets){const n=MONTHS[t.m-1]+' '+t.y; if(titles.includes(n)&&!tabs.includes(n)) tabs.push(n);}
const q=s=>"'"+s+"'";
const filters=tabs.length? tabs.map(t=>({a1Range:q(t)+'!A1:O2000'})) : [{a1Range:q('הגדרות')+'!A1:A1'}];
return {tabs:tabs.join(', '), targets:JSON.stringify(targets), readBody:JSON.stringify({dataFilters:filters, valueRenderOption:'FORMATTED_VALUE'})};

const TEST=false;
const GROUP='120363403845988381@g.us';
const STEVE='972544604246@c.us';
const MONTHS=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const DAYS=['ראשון','שני','שלישי','רביעי','חמישי','שישי','שבת'];
const arr=v=>{ if(typeof v==='string'){ try{return JSON.parse(v);}catch(e){return [];} } return Array.isArray(v)?v:[]; };
const norm=s=>String(s==null?'':s).replace(/\s+/g,' ').trim();
const targets=arr(input.targets);
const key=t=>t.y+'-'+t.m+'-'+t.d;
const want={}; targets.forEach(t=>{want[key(t)]=[];});
const parseDate=s=>{ s=norm(s); let m=s.match(/(\d{1,2})\s+(\S+)\s+(\d{4})/); if(m){const mi=MONTHS.indexOf(m[2]); if(mi>=0) return {y:+m[3],m:mi+1,d:+m[1]};} m=s.match(/(\d{1,2})[\/.](\d{1,2})[\/.](\d{2,4})/); if(m){let y=+m[3]; if(y<100) y+=2000; return {y:y,m:+m[2],d:+m[1]};} return null; };
const slotStart=s=>{const m=String(s).match(/(\d{1,2}):/);return m?+m[1]:99;};
for(const vr of arr(input.ranges)){
  const v=(vr&&vr.valueRange)||vr||{};
  const vals=arr(v.values);
  for(let i=1;i<vals.length;i++){
    const r=vals[i]||[];
    const dt=parseDate(r[4]); if(!dt) continue;
    const k=dt.y+'-'+dt.m+'-'+dt.d; if(!want[k]) continue;
    if(/תשתיות/.test(norm(r[12]))) continue;
    if(!norm(r[2])&&!norm(r[6])) continue;
    want[k].push({name:norm(r[2]),phone:norm(r[3]),slot:norm(r[5]),num:norm(r[6]),rep:norm(r[7])});
  }
}
// RULE (Steve 08/11/2026): group the list by rep name, so each rep sees their installs clearly.
const line=x=>'• '+[x.slot,x.name,x.phone,x.num].filter(Boolean).join(' | ');
let count=0; const parts=[];
for(const t of targets){
  const rows=want[key(t)].sort((a,b)=>slotStart(a.slot)-slotStart(b.slot));
  count+=rows.length;
  if(!rows.length) continue;
  const byRep={}; const order=[];
  rows.forEach(x=>{const r=x.rep||'ללא נציג'; if(!byRep[r]){byRep[r]=[];order.push(r);} byRep[r].push(x);});
  const hdr='*התקנות ליום '+DAYS[t.w]+' '+t.d+'/'+t.m+'* ('+rows.length+' לקוחות)';
  parts.push(hdr+'\n\n'+order.map(r=>'*'+r+'* ('+byRep[r].length+')\n'+byRep[r].map(line).join('\n')).join('\n\n'));
}
let message=parts.join('\n\n━━━━━━━━━━\n\n');
if(count) message+='\n\nתבדקו שהלקוחות שלכם חתמו ומוכנים להתקנה.';
if(TEST) message='[בדיקה - נשלח רק אליך]\n'+message;
return {count, message, chatId: TEST?STEVE:GROUP};
